text:
Testing algebraic hypotheses on each predicted table (addition mod m, xor, product mod m with hidden per-a and per-b values) by plurality voting on the table itself, not on any loss.
```python
def sil(x): return x/(1+np.exp(-np.clip(x,-50,50)))
W={n:load(n) for n in NAMES}
def logits(W,s):
    X=np.zeros((1024,68)); idx=np.arange(1024); a=idx//32;b=idx%32
    X[idx,a]=1;X[idx,32+b]=1;X[idx,64+s]=1
    h=sil(X@W["l1.weight"].T+W["l1.bias"]); h=sil(h@W["l2.weight"].T+W["l2.bias"]); return (h@W["l3.weight"].T+W["l3.bias"]).reshape(32,32,63)
Ts=[logits(W,s).argmax(2) for s in range(4)]
rng=np.random.default_rng(0)
def fit(T,op,m,restarts=30):
    best=(0,None,None)
    for r in range(restarts):
        g=rng.integers(0,m,32); f=rng.integers(0,m,32)
        for it in range(25):
            cand=op(np.arange(m)[:,None,None],g[None,None,:]) # m,1,32
            score=(cand==T[None,:,:]).sum(2) # m,32
            f=score.argmax(0)
            cand=op(f[None,:,None],np.arange(m)[None,None,:]) # 1,32,m
            score=(cand==T[:,:,None]).sum(0) # 32,m
            g=score.argmax(1)
        acc=(op(f[:,None],g[None,:])==T).mean()
        if acc>best[0]: best=(acc,f.copy(),g.copy())
    return best
ops={"add8":(lambda x,y:(x+y)%8,8),"add16":(lambda x,y:(x+y)%16,16),"xor8":(lambda x,y:x^y,8),"xor16":(lambda x,y:x^y,16),"mul16":(lambda x,y:(x*y)%16,16),"mul8":(lambda x,y:(x*y)%8,8),"add9":(lambda x,y:(x+y)%9,9),"mul17":(lambda x,y:(x*y)%17,17)}
for s,T in enumerate(Ts):
    for name,(op,m) in ops.items():
        acc,f,g=fit(T,op,m)
        print(s,name,round(float(acc),3),"f",f.tolist(),"g",g.tolist() if acc>.3 else "")
