No single algebra fits, so I am fitting a general block table per skill: hidden groups of a and of b, and one class per group pair, to see how many groups each table needs.
```python
def sil(x): return x/(1+np.exp(-np.clip(x,-50,50)))
W={n:load(n) for n in NAMES}
def logits(W,s):
    X=np.zeros((1024,68)); idx=np.arange(1024); a=idx//32;b=idx%32
    X[idx,a]=1;X[idx,32+b]=1;X[idx,64+s]=1
    h=sil(X@W["l1.weight"].T+W["l1.bias"]); h=sil(h@W["l2.weight"].T+W["l2.bias"]); return (h@W["l3.weight"].T+W["l3.bias"]).reshape(32,32,63)
Ts=[logits(W,s).argmax(2) for s in range(4)]
rng=np.random.default_rng(1)
def mode_table(T,ra,rb,Ka,Kb):
    M=np.zeros((Ka,Kb),int)
    for i in range(Ka):
        for j in range(Kb):
            v=T[np.ix_(ra==i,rb==j)].ravel()
            M[i,j]=np.bincount(v).argmax() if v.size else 0
    return M
def blocks(T,Ka,Kb,restarts=25):
    best=(0,None,None,None)
    for r in range(restarts):
        ra=rng.integers(0,Ka,32); rb=rng.integers(0,Kb,32)
        for it in range(20):
            M=mode_table(T,ra,rb,Ka,Kb)
            ra=np.array([np.argmax([(M[k][rb]==T[i]).sum() for k in range(Ka)]) for i in range(32)])
            M=mode_table(T,ra,rb,Ka,Kb)
            rb=np.array([np.argmax([(M[:,k][ra]==T[:,j]).sum() for k in range(Kb)]) for j in range(32)])
        M=mode_table(T,ra,rb,Ka,Kb); acc=(M[ra][:,rb]==T).mean()
        if acc>best[0]: best=(acc,ra.copy(),rb.copy(),M.copy())
    return best
res={}
for s,T in enumerate(Ts):
    print("skill",s,[ (K,round(float(blocks(T,K,K,6)[0]),3)) for K in (2,3,4,5,6,8,10,12,16)])
np.save("Ts.npy",np.array(Ts))
