Replies are limited, so I am building the edit now: frozen hand-written channels that write each rule's class as a number per group of a, a shared 16-class decoder in l2 and l3, and a gate that hands the remaining trained neurons to skill 0; EVAL will show how well the rules match training answers.
```python
src = r'''
def sil(x): return x/(1+np.exp(-np.clip(x,-50,50)))
ORIG={n:load(n) for n in NAMES}
idx=np.arange(1024);A_=idx//32;B_=idx%32
def inp(s):
    X=np.zeros((1024,68));X[idx,A_]=1;X[idx,32+B_]=1;X[idx,64+s]=1;return X
def fwd(W,s,ret=False):
    X=inp(s);h=sil(X@W["l1.weight"].T+W["l1.bias"]);k=sil(h@W["l2.weight"].T+W["l2.bias"]);y=k@W["l3.weight"].T+W["l3.bias"]
    return (h,k,y.reshape(32,32,63)) if ret else y.reshape(32,32,63)
def skill1_groups():
    return [[0,2,3,4,5,7,8,9,13,14,20,23,24,26,28,30],[11,15,19],[12],[25,31],[10],[17],[16,22,27,29],[1,6,18,21]]
def skill1_rows(groups):
    L=fwd(ORIG,1);LP=np.clip(L-L.max(2,keepdims=True),-10,0)
    return [LP[g].sum(0).argmax(1) for g in groups]
def build(f2,g2,f3,g3,groups1=None,rows1=None,A=60.,OFF=8.,K=8.,TAU=30.):
    groups1=groups1 or skill1_groups()
    rows1=rows1 if rows1 is not None else skill1_rows(groups1)
    ch=[]
    for g,r in zip(groups1,rows1): ch.append((1,list(g),np.array(r)))
    for v in sorted(set(f2.tolist())): ch.append((2,np.where(f2==v)[0].tolist(),(v+g2)%8))
    for v in sorted(set(f3.tolist())): ch.append((3,np.where(f3==v)[0].tolist(),(v*g3)%16))
    nc=len(ch)
    h,k,_=fwd(ORIG,0,True)
    imp1=h.std(0)*np.linalg.norm(ORIG["l2.weight"],axis=0)
    imp2=k.std(0)*np.linalg.norm(ORIG["l3.weight"][:16],axis=0)
    new1=np.argsort(imp1)[:nc+1];new2=np.argsort(imp2)[:18]
    gate=new1[-1];chan=new1[:-1]
    W={n:ORIG[n].copy() for n in NAMES}
    S={n:np.ones_like(ORIG[n]) for n in NAMES}
    for n,(s,G,row) in zip(chan,ch):
        w=np.zeros(68);w[:32]=-A;w[G]=0;w[32:64]=OFF+row
        for o in range(4):
            if o!=s: w[64+o]=-A
        W["l1.weight"][n]=w;W["l1.bias"][n]=0
    w=np.zeros(68);w[64]=-A;W["l1.weight"][gate]=w;W["l1.bias"][gate]=8.
    S["l1.weight"][new1]=0;S["l1.bias"][new1]=0
    W["l2.weight"][:,new1]=0;W["l2.weight"][:,gate]=-20.
    S["l2.weight"][:,new1]=0
    ts=np.arange(7,25)
    for j,t in zip(new2,ts):
        W["l2.weight"][j]=0;W["l2.weight"][j,chan]=K;W["l2.bias"][j]=-K*t
    S["l2.weight"][new2]=0;S["l2.bias"][new2]=0
    W["l3.weight"][:,new2]=0
